import{_ as a,c as r,o as t,a0 as i}from"./chunks/framework.C1J0Vcxi.js";const b=JSON.parse('{"title":"第七周：星光二平台调试成功、构建移植项目仓库、阅读opensbi+uboot文档","description":"","frontmatter":{"title":"第七周：星光二平台调试成功、构建移植项目仓库、阅读opensbi+uboot文档","date":"2025-12-13"},"headers":[],"relativePath":"周报-Oveln/archive/2025-12-13-周报七.md","filePath":"周报-Oveln/archive/2025-12-13-周报七.md"}'),o={name:"周报-Oveln/archive/2025-12-13-周报七.md"};function l(n,e,s,h,c,d){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="第七周工作总结" tabindex="-1">第七周工作总结 <a class="header-anchor" href="#第七周工作总结" aria-label="Permalink to &quot;第七周工作总结&quot;">​</a></h1><h2 id="星光二平台调试成功、官方文档错误" tabindex="-1">星光二平台调试成功、官方文档错误 <a class="header-anchor" href="#星光二平台调试成功、官方文档错误" aria-label="Permalink to &quot;星光二平台调试成功、官方文档错误&quot;">​</a></h2><p>详见我的步骤社区帖子 <a href="https://forum.rvspace.org/t/jlink-s76/5810/6" target="_blank" rel="noreferrer">用Jlink调试S76核心</a></p><h2 id="固件编译" tabindex="-1">固件编译 <a class="header-anchor" href="#固件编译" aria-label="Permalink to &quot;固件编译&quot;">​</a></h2><ul><li><strong>编译固件</strong>: 使用上游<code>opensbi</code>+上游<code>u-boot</code>编译出spl+u-boot固件，烧录到芯片后成功</li></ul><h2 id="构建移植项目仓库" tabindex="-1">构建移植项目仓库 <a class="header-anchor" href="#构建移植项目仓库" aria-label="Permalink to &quot;构建移植项目仓库&quot;">​</a></h2><p><a href="https://github.com/Oveln/embassy_preempt_VisionFive2/" target="_blank" rel="noreferrer">embassy_preempt_VisionFive2</a></p><h3 id="使用nix管理环境" tabindex="-1">使用nix管理环境 <a class="header-anchor" href="#使用nix管理环境" aria-label="Permalink to &quot;使用nix管理环境&quot;">​</a></h3><ul><li><strong>nix</strong>：因为项目所需构建环境比较复杂，使用nix进行环境管理能够一键重现、以及方便版本管理</li><li><strong>使用方案</strong>：使用进入项目根目录后使用<code>nix develop</code></li></ul><h3 id="使用-makefile-构建itb镜像" tabindex="-1">使用 Makefile 构建itb镜像 <a class="header-anchor" href="#使用-makefile-构建itb镜像" aria-label="Permalink to &quot;使用 Makefile 构建itb镜像&quot;">​</a></h3><ul><li><strong>Makefile</strong>：使用make uboot一键构建镜像</li></ul><h2 id="下周计划" tabindex="-1">下周计划 <a class="header-anchor" href="#下周计划" aria-label="Permalink to &quot;下周计划&quot;">​</a></h2><ul><li><strong>尝试通过jtag接口烧录固件</strong>：能够方便开发调试。发邮件尝试联系了github上probe-rs的jh7110的flash算法的作者，目前还没有回复</li><li><strong>修改opensbi</strong>：已经在正确的地方用hart0输出了日志，只需在该位置跳转到rust代码即可</li><li><strong>构建embassy_preempt jh7110 platform抽象</strong>：架构是riscv64imc，需要从之前的ch32v307移植，修改相关汇编为64位</li></ul><h3 id="相关资料" tabindex="-1">相关资料 <a class="header-anchor" href="#相关资料" aria-label="Permalink to &quot;相关资料&quot;">​</a></h3><ul><li><a href="https://bbs.scumaker.org/t/topic/465" target="_blank" rel="noreferrer">[记录] Boot JH7110 From Scratch</a></li><li><a href="https://doc.rvspace.org/VisionFive2/PDF/VisionFive2_SW_TRM.pdf" target="_blank" rel="noreferrer">昉·星光 2单板计算机软件技术参考手册</a></li><li><a href="https://doc.rvspace.org/VisionFive2/FAQ/VisionFive_2/j_link.html" target="_blank" rel="noreferrer">RVspace 昉·星光 2常见问题集</a></li><li><a href="https://doc.rvspace.org/VisionFive2/PDF/VisionFive2_QSG.pdf" target="_blank" rel="noreferrer">昉·星光 2单板计算机快速参考手册</a></li><li><a href="https://forum.rvspace.org/t/jtag-ports/890" target="_blank" rel="noreferrer">社区帖子-JTAG ports?</a></li></ul>',15)])])}const _=a(o,[["render",l]]);export{b as __pageData,_ as default};
